 const [backupMsg,setBackupMsg]=useState('');
 function exportBackup(){const notes:Record<string,string>={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i)!;if(k.startsWith('biblical_notes_'))notes[k]=localStorage.getItem(k)||'';}const data={app:'estudios-ramela-backup',version:1,exportedAt:new Date().toISOString(),edits,drafts,imported,notes};const blob=new Blob([JSON.stringify(data,null,1)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='copia-estudios-ramela-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setBackupMsg('Copia guardada en Descargas: '+Object.keys(edits).length+' estudios editados, '+drafts.length+' borradores, '+imported.length+' importados.');}
 async function importBackup(file:File){try{const d=JSON.parse(await file.text());if(d.app!=='estudios-ramela-backup'||typeof d.edits!=='object')throw Error();const ne={...edits};let e=0;for(const [id,v] of Object.entries<Edit>(d.edits||{})){if(!ne[id]||ne[id].editedAt<v.editedAt){ne[id]=v;e++;}}const mergeById=(a:SavedStudy[],b:SavedStudy[])=>{const ids=new Set(a.map(x=>x.id));return [...a,...(b||[]).filter(x=>!ids.has(x.id))];};const nd=mergeById(drafts,d.drafts),ni=mergeById(imported,d.imported);for(const [k,v] of Object.entries<string>(d.notes||{})){if(!localStorage.getItem(k))localStorage.setItem(k,v);}localStorage.setItem('study_edits',JSON.stringify(ne));localStorage.setItem('biblical_drafts',JSON.stringify(nd));localStorage.setItem('reviewed_library_imports',JSON.stringify(ni));setEdits(ne);setDrafts(nd);setImported(ni);setBackupMsg('Copia restaurada. Se usó la versión más reciente de cada estudio; nada se borró. Estudios editados recuperados: '+e+'.');}catch{setBackupMsg('No se pudo abrir ese archivo. Usá una copia creada desde esta app.');}}
 function saveEdit(r:{title:string;content:string}){const prev=edits[study.id];const now=new Date().toISOString();const next={...edits,[study.id]:{title:r.title,content:r.content,editedAt:now,previous:[...(prev?[{title:prev.title,content:prev.content,editedAt:prev.editedAt}]:[]),...(prev?.previous||[])].slice(0,10)}};try{localStorage.setItem('study_edits',JSON.stringify(next));}catch{alert('No se pudo guardar: el espacio del dispositivo está lleno.');return;}setEdits(next);setEditing(false);}
 function undoEdit(){if(!edit)return;if(!confirm('¿Volver a la versión anterior de este estudio?'))return;const [last,...rest]=edit.previous;const next={...edits};if(last)next[study.id]={...edit,title:last.title,content:last.content,editedAt:last.editedAt,previous:rest};else delete next[study.id];localStorage.setItem('study_edits',JSON.stringify(next));setEdits(next);}
 function restoreOriginal(){if(!confirm('¿Volver al texto original? Se descartan tus cambios en este estudio.'))return;const next={...edits};delete next[study.id];localStorage.setItem('study_edits',JSON.stringify(next));setEdits(next);}
 const sections=study.content.split("\n").filter(l=>l.startsWith("## ")).map(l=>l.slice(3).replace(/[:.]\s*$/,"").trim());
